<script setup lang="ts">
import { ArrowLeft,ArrowRight,CheckCircle2,Clock3,Wallet,FileText,Info,ToggleRight,ToggleLeft } from 'lucide-vue-next'
import type { Procedure } from '~/types/models'
const route=useRoute()
const {data:p,error,refresh}=await useFetch<Procedure>(`/api/procedures/${route.params.slug}`, {key:`staff-procedure:${String(route.params.slug)}`})
const busy=ref(false);const result=ref('')
async function togglePublish(){if(busy.value)return;busy.value=true;result.value='';try{await $fetch(`/api/procedures/${route.params.slug}/publish`,{method:'POST',body:{published:!p.value?.published}});result.value='Đã cập nhật trạng thái công bố thủ tục.';await refresh();await refreshNuxtData(['staff-procedures',`staff-procedure:${String(route.params.slug)}`])}catch(e){result.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><NuxtLink to="/thu-tuc" class="inline-flex items-center gap-1 text-sm font-bold text-brand-700"><ArrowLeft :size="16"/> Quay về danh mục thủ tục</NuxtLink>
 <div v-if="error" class="panel p-6 text-rose-700">Không tìm thấy thủ tục.</div><template v-else-if="p"><div class="panel p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="mb-1 text-xs font-bold uppercase tracking-wide text-brand-600">{{p.category}}</p><h2 class="text-2xl font-extrabold">{{p.title}}</h2><p class="mt-2 text-sm text-muted">{{p.summary}}</p></div><div class="flex items-center gap-2"><span :class="['rounded-full px-3 py-1 text-[11px] font-bold',p.published?'bg-green-100 text-green-700':'bg-slate-100 text-slate-600']">{{p.published?'Đang công bố':'Chưa công bố'}}</span><button class="btn-outline sm:px-4" :disabled="busy" @click="togglePublish"><ToggleRight :size="16" v-if="!p.published"/><ToggleLeft :size="16" v-else/>{{busy?'Đang cập nhật...':p.published?'Ẩn khỏi công khai':'Công bố cho công dân'}}</button></div></div></div>
 <div class="grid gap-4 md:grid-cols-2"><section class="panel p-5"><h3 class="section-label"><Info :size="21" class="text-brand-600"/>Điều kiện và cách thực hiện</h3><p class="text-sm leading-7 text-slate-700">{{p.instructions}}</p><p class="mt-4 rounded-lg bg-amber-50 p-3 text-xs text-amber-800">Các nội dung thủ tục và mức phí đang mô phỏng. Hãy đối chiếu văn bản pháp lý hiện hành trước khi vận hành thật.</p></section><section class="panel p-5"><h3 class="section-label"><FileText :size="21" class="text-brand-600"/>Thành phần giấy tờ cần chuẩn bị</h3><div v-for="(doc,i) in p.documents" :key="doc.document_code" class="flex items-start gap-2 border-b border-slate-100 py-3 text-sm last:border-0"><CheckCircle2 :size="18" class="mt-0.5 shrink-0 text-green-500"/><span>{{i+1}}. {{doc.document_name}} <span v-if="doc.is_required" class="text-rose-500">*</span></span></div></section></div>
 <div class="grid gap-3 sm:grid-cols-3"><div class="stat-tile flex items-center gap-3"><Clock3 :size="23" class="text-brand-600"/><span><small class="block text-muted">Thời hạn (mẫu)</small><b>{{p.sla_days}} ngày làm việc</b></span></div><div class="stat-tile flex items-center gap-3"><Wallet :size="23" class="text-brand-600"/><span><small class="block text-muted">Phí (mẫu)</small><b>{{p.fee_note}}</b></span></div><div class="stat-tile flex items-center gap-3"><FileText :size="23" class="text-brand-600"/><span><small class="block text-muted">Cách thức</small><b>Nộp trực tuyến</b></span></div></div>
 <p v-if="result" class="rounded-lg bg-brand-50 p-3 text-sm text-brand-800">{{result}}</p></template></div></template>
